fn extract_use_markdown(&mut self, call_expr: &CallExpr, var_decl: &VarDeclarator) {
    // Check if parent is VarDeclarator with ArrayPattern
    let (content_var, setter_var) = match &var_decl.name {
        Pat::Array(arr_pat) => {
            let content = arr_pat.elems.get(0)
                .and_then(|e| e.as_ref())
                .and_then(|p| if let Pat::Ident(id) = p { Some(id.id.sym.to_string()) } else { None });
            let setter = arr_pat.elems.get(1)
                .and_then(|e| e.as_ref())
                .and_then(|p| if let Pat::Ident(id) = p { Some(id.id.sym.to_string()) } else { None });
            (content, setter)
        }
        _ => return,
    };

    let initial_value = call_expr.args.get(0).map(|arg| &*arg.expr);

    if let Some(component) = &mut self.current_component {
        component.use_markdown.push(UseMarkdown {
            name: content_var.unwrap_or_default(),
            setter: setter_var.unwrap_or_default(),
            initial_value: self.generate_csharp_expression(initial_value),
        });

        // Track as markdown state type
        if let Some(name) = content_var {
            component.state_types.insert(name, "markdown".to_string());
        }
    }
}
